bool isSubsequence(const std::string& s, const std::string& t) {
    std::size_t i = 0;
    for (std::size_t j = 0; i < s.size() && j < t.size(); j++) {
        if (s[i] == t[j]) {
            i++;
        }
    }
    return i == s.size();
}

