package main

import (
	"bufio"
	"fmt"
	"os"
)

func isSubsequence(s, t string) bool {
	// s[i] and t[j] are bytes, one per letter, since the input is plain ASCII.
	i := 0
	for j := 0; i < len(s) && j < len(t); j++ {
		if s[i] == t[j] {
			i++
		}
	}
	return i == len(s)
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	s := scanner.Text()
	scanner.Scan()
	t := scanner.Text()
	fmt.Println(isSubsequence(s, t))
}

